  const parsed=output.parsed_decision||{},validation=output.deterministic_validation||{},parts=validation.rule_score_components||{},effects=receipt.effects||{},archive=receipt.archive||{};
  const partLabels={timeframe_alignment:"周期一致性",signal_strength:"信号强度",regime_fit:"状态适配",data_health:"数据健康",historical_calibration:"历史校准"};
  const scores=Object.entries(parts).map(([key,value])=>`<div><span>${partLabels[key]||esc(key)}</span><b>${num(value)}</b></div>`).join("");
