function fillInputs(plan,{force=false}={}){
  if(state.formDirty&&!force)return;
  state.draftProblem=null;
  if(isDca(plan?.strategy_type)){
    const dca=plan?.dca||{},entries=dca.entries||[],prices=entries.map(row=>Number(row.price)).filter(Number.isFinite),risk=plan?.risk_budget||{};
    state.strategyType="dca";state.direction=plan?.direction||"long";if(!["long","short"].includes(state.direction))state.direction="long";
    $("#rangeLow").value=prices.length?Math.min(...prices):"";$("#rangeHigh").value=prices.length?Math.max(...prices):"";$("#gridCount").value=dca.max_additions??entries.length??"";$("#gridNotional").value=dca.notional_per_addition??"";$("#dcaTarget").value=dca.target_price??"";$("#dcaStop").value=dca.stop_price??"";$("#leverage").value=risk.selected_leverage??risk.leverage_limit??10;
    setChoice("#directionChoices","direction",state.direction);setStrategyTypeUi();return;
  }
  const range=plan?.range||{},grid=plan?.grid||{};
  $("#rangeLow").value=range.low??"";$("#rangeHigh").value=range.high??"";$("#gridCount").value=grid.count??"";$("#gridProfitTarget").value=grid.target_net_profit_per_grid_usd??10;$("#gridNotional").value=grid.notional_per_grid??"";$("#leverage").value=grid.leverage??plan?.risk_budget?.leverage??10;
  state.strategyType="grid";state.gridMode=grid.mode||"arithmetic";
  state.direction=plan?.direction||"neutral";state.style=plan?.style||"steady";setChoice("#directionChoices","direction",state.direction);setChoice("#styleChoices","style",state.style);setGridMode(state.gridMode);
  setStrategyTypeUi();renderParameterLocks();
}

