const CLOSE_FILL_EVENTS=new Set(["exit","stop","target","take_profit","stop_loss","flatten"]);
function activityLineage(row,related){return String(row?.source_cycle_id||row?.cycle_id||row?.strategy_plan_id||related?.source_cycle_id||related?.cycle_id||related?.strategy_plan_id||"").trim()}
