function tradeActivityFactsTrusted(accounting){const reconciliation=String(accounting?.reconciliation?.status||"").toLowerCase(),observed=accounting?.completeness?.observed||{};return["pass","ok"].includes(reconciliation)&&observed.fills_observed===true&&observed.trades_observed===true&&observed.positions_observed===true}
