async function refreshMarket(){const symbol=chartSymbol(),timeframe=state.timeframe,{key,generation}=switchMarketDataset(symbol,timeframe),requestSequence=++state.marketRequestSequence,isCurrent=()=>requestSequence===state.marketRequestSequence&&generation===state.marketGeneration&&key===state.marketDatasetKey&&timeframe===state.timeframe;try{const [incoming]=await Promise.all([api(dashboardMarketBarsUrl({symbol,timeframe,limit:240})),timeframe==="1m"?null:refreshExecutionMarket(symbol)]);if(!isCurrent())return null;state.market=acceptMarketSnapshot(incoming);if(timeframe==="1m")keepExecutionMarket(symbol,state.market);const failure=isFresh(incoming)?null:tradingFailure(marketFailure(incoming));setHistoryNotice(failure?`${failure.text}${state.market?.retained_last_trusted?" 已保留最后可信 K 线，仅供查看；":""}禁止新开仓。`:"向左滚动或向右拖动图表，可加载更早 K 线。");render();return state.market}catch(error){if(!isCurrent())return null;const failure=tradingFailure(error);state.market=retainLastTrustedMarket(state.market,{status:"error",message:failure.text});if(timeframe==="1m")keepExecutionMarket(symbol,state.market);setHistoryNotice(`${failure.text}${state.market?.retained_last_trusted?" 已保留最后可信 K 线，仅供查看；":""}禁止新开仓。`);render();return state.market}}
async function load({withMarket=true}={}){try{const [data,auth]=await Promise.all([api('/api/trading-system/read-model'),gmRead.readSession(api,PUBLIC_OBSERVER)]);state.readError=null;applyReadModel(data);state.auth=auth;if(!dashboardMarketBinding()&&!paperGoldSelected())state.market=reconcileReadModelMarket(state.market,data.market);render();if(withMarket)await refreshMarket();await refreshDailyMarket(state.market||data.market);render()}catch(error){const failure=tradingFailure(error);state.readError=failure.text;window.gridmindView=Object.freeze({...(window.gridmindView||{}),readError:failure.text});publishHeader({marketClass:"pill run-state error",marketLabel:"运行异常",runClass:"top-status",runText:failure.text});setNotice(failure.text);setHistoryNotice(failure.text)}}
async function loadSupervisorAudit(){const cycleId=readModelCycleId(state.data);if(!cycleId||state.supervisorAuditCycle===cycleId&&state.supervisorAudit)return;if(state.supervisorAuditRequest)return state.supervisorAuditRequest;$("#supervisor").insertAdjacentHTML("afterbegin",'<div id="supervisorAuditLoading" class="review-trace">正在按需读取完整、不可变的 Supervisor 审计……</div>');state.supervisorAuditRequest=(async()=>{try{const response=await api(`/api/trading-system/supervisor-history?cycle_id=${encodeURIComponent(cycleId)}`);if(response?.cycle_id!==cycleId||response?.completeness?.status!=="complete"||!response?.supervisor)throw apiFailure("Supervisor 完整审计不可用",503,"supervisor_history_unavailable");if(readModelCycleId(state.data)!==cycleId)return;state.supervisorAuditCycle=cycleId;state.supervisorAudit=response.supervisor;if(state.data?.runtime)state.data.runtime.supervisor=state.supervisorAudit;renderSupervisor(state.data)}catch(error){const target=$("#supervisorAuditLoading");if(target)target.textContent=`完整审计读取失败：${error.message}`;throw error}finally{state.supervisorAuditRequest=null}})();return state.supervisorAuditRequest}
function showStartFailureDialog(message){const dialog=$("#startFailureDialog");$("#startFailureReason").textContent=message||"后台拒绝了启动请求。";if($("#startRiskDialog")?.open)$("#startRiskDialog").close();if(!dialog.open)dialog.showModal()}
async function runButton(button,pending,work,options={}){return gmControl.runButton(controlHost,pending,work,options)}
function redrawChart(){renderChart(state.market||state.data?.market,displayPlan(state.data),state.data?.execution||{})}

$("#timeframe").addEventListener("change",async event=>{state.timeframe=event.target.value;await refreshMarket()});
$("#timeframeButtons").addEventListener("click",async event=>{if(event.target.closest("[data-tf-more]")){state.timeframesOpen=!state.timeframesOpen;renderTimeframes(state.data);return}const button=event.target.closest("[data-tf]");if(!button)return;state.timeframe=button.dataset.tf;await refreshMarket()});
$("#gridAdjustToggle").addEventListener("click",toggleGridAdjustMode);
$("#refreshTrend").addEventListener("click",event=>runButton(event.currentTarget,"正在重新评估市场",async()=>{const result=await control('refresh_recommendation',{}, {reload:false});setNotice(`AI 已提出${planDirection(result.proposal)} · ${styleLabel(result.proposal?.style)}建议；规则评分 ${num(result.proposal?.signal?.rule_score)}/100（未校准）。生产计划未改变。`);await load()}));
$("#trendBox").addEventListener("click",async event=>{const receiptButton=event.target.closest("#openAiReceipt");if(receiptButton){openAiReceipt(latestRecommendation(state.data)?.evaluation_receipt?.evaluation_id);return}if(state.gridAdjustMode||!event.target.closest("#adoptRecommendation"))return;const recommendation=latestRecommendation(state.data);if(!recommendation)return;const framework=recommendation.framework||recommendation.analysis?.framework||{},suggestedType=String(framework?.strategy?.recommended_strategy_type||recommendation.strategy_type||"grid").toLowerCase(),nextType=["grid","dca"].includes(suggestedType)?suggestedType:"grid",nextDirection=nextType==="dca"&&!["long","short"].includes(recommendation.direction)?"long":recommendation.direction;state.direction=nextDirection;state.style=recommendation.style;setChoice("#directionChoices","direction",state.direction);setChoice("#styleChoices","style",state.style);if(nextType!==state.strategyType){await selectStrategyType(nextType);return}if(isDca())fillDcaFromMarket();requestPreview({useInputs:isDca()}).catch(()=>{})});
$("#closeAiReceipt").addEventListener("click",()=>$("#aiReceiptDialog").close());
$("#aiReceiptHistory").addEventListener("change",event=>{openAiReceipt(event.target.value)});
$("#aiReceiptDialog").addEventListener("click",event=>{if(event.target===$("#aiReceiptDialog"))$("#aiReceiptDialog").close()});
$("#closeGridRangeReview").addEventListener("click",closeGridRangeReview);$("#keepGridRangeDraft").addEventListener("click",closeGridRangeReview);$("#cancelGridRangeReview").addEventListener("click",clearGridRangeDraft);$("#executeGridRangeReplacement").addEventListener("click",executeGridRangeReplacement);$("#gridRangeReviewDialog").addEventListener("cancel",event=>{event.preventDefault();if(!state.gridReplacementPending)closeGridRangeReview()});$("#gridRangeReviewDialog").addEventListener("click",event=>{if(event.target===$("#gridRangeReviewDialog")&&!state.gridReplacementPending)closeGridRangeReview()});
gmIntent.on("gesture","grid.dragEnd",({args})=>finishGridDrag(args.event,{commit:args.commit}));
gmIntent.on("click","startRisk.close",()=>{if(!state.busy)$("#startRiskDialog").close()});$("#startRiskDialog").addEventListener("cancel",event=>{event.preventDefault();if(!state.busy)$("#startRiskDialog").close()});gmIntent.on("click","startRisk.confirm",event=>startRiskConfirmDisabled()?undefined:runButton(event.currentTarget,"正在重新核对风险并启动机器人",async()=>performStartRobot({acknowledge:true}),{failureSurface:"dialog"}));
/* click, and a toggle of state: React restores a controlled checkbox during the click, so input.checked cannot be trusted by the time change fires (#1397). */
gmIntent.on("click","startRisk.ack",event=>{toggleStartRiskAck(String(event.currentTarget.dataset.startRiskAck||""));renderStartRiskReview()});
const closeStartFailure=()=>{const dialog=$("#startFailureDialog");if(dialog.open)dialog.close()};$("#closeStartFailure").addEventListener("click",closeStartFailure);$("#dismissStartFailure").addEventListener("click",closeStartFailure);$("#startFailureDialog").addEventListener("cancel",event=>{event.preventDefault();closeStartFailure()});
gmIntent.on("click","strategy.type",event=>{const button=event.target.closest("[data-strategy-type]");if(button)selectStrategyType(button.dataset.strategyType)});
$("#directionChoices").addEventListener("click",event=>{if(state.gridAdjustMode)return;const button=event.target.closest("[data-direction]");if(!button||button.disabled)return;state.direction=button.dataset.direction;setChoice("#directionChoices","direction",state.direction);if(isDca())fillDcaFromMarket();requestPreview({useInputs:isDca()}).catch(()=>{})});
$("#styleChoices").addEventListener("click",event=>{if(state.gridAdjustMode)return;const button=event.target.closest("[data-style]");if(!button)return;state.style=button.dataset.style;setChoice("#styleChoices","style",state.style);requestPreview({useInputs:false}).catch(()=>{})});
$("#gridModeChoices").addEventListener("click",event=>{if(state.gridAdjustMode)return;const button=event.target.closest("[data-grid-mode]");if(!button)return;const previousMode=state.gridMode;state.gridMode=button.dataset.gridMode;setGridMode(state.gridMode);requestPreview({useInputs:false}).catch(()=>{state.gridMode=previousMode;setGridMode(previousMode);redrawChart()})});
$("#smartFill").addEventListener("click",()=>{if(state.gridAdjustMode)return;if(isDca()){try{fillDcaFromMarket();setStrategyTypeUi();requestPreview({useInputs:true}).catch(()=>{})}catch(error){$("#paramHint").textContent=error.message}return}state.parameterLocks.delete("range");renderParameterLocks();requestPreview({useInputs:false}).catch(()=>{})});
[["#rangeLow","range"],["#rangeHigh","range"],["#gridCount","grid_count"],["#gridProfitTarget","profit_target"],["#gridNotional","notional_per_grid"],["#leverage","leverage"]].forEach(([selector,name])=>$(selector).addEventListener("input",()=>{if(!isDca())lockParameter(name);schedulePreview()}));
[$("#dcaTarget"),$("#dcaStop")].forEach(input=>input.addEventListener("input",schedulePreview));
$$('[data-param-lock]').forEach(button=>button.addEventListener("click",()=>{const name=String(button.dataset.paramLock);state.parameterLocks.delete(name);renderParameterLocks();requestPreview({useInputs:true}).catch(()=>{})}));
$("#showEma").addEventListener("change",event=>{state.indicators.ema=event.target.checked;redrawChart()});$("#showMacd").addEventListener("change",event=>{state.indicators.macd=event.target.checked;redrawChart()});
["#emaFast","#emaSlow"].forEach((selector,index)=>$(selector).addEventListener("change",event=>{const value=Math.round(Number(event.target.value));if(!Number.isInteger(value)||value<2||value>300){event.target.value=state.indicators[index?"slow":"fast"];return}state.indicators[index?"slow":"fast"]=value;if(state.indicators.fast>=state.indicators.slow){state.indicators.slow=state.indicators.fast+1;$("#emaSlow").value=state.indicators.slow}redrawChart()}));
gmIntent.on("click","robot.start",event=>state.robot.start.disabled?undefined:runButton(event.currentTarget,"正在核对启动参数",()=>gmControl.startRobot(controlHost),{failureSurface:"dialog"}));
gmIntent.on("click","robot.stop",event=>state.robot.stop.disabled?undefined:runButton(event.currentTarget,"正在停止、撤单并平仓",()=>gmControl.stopRobot(controlHost)));
$("#positions").addEventListener("click",async event=>{if(state.gridAdjustMode||state.busy)return;const button=event.target.closest("[data-close]");if(!button)return;try{const data=state.data,positionSide=button.dataset.side,exitSide=["buy","long"].includes(positionSide)?"sell":"buy";setNotice("正在提交手动平仓。");await api('/api/dualtrack/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({cycle_id:data.cycle.cycle_id,trade_id:button.dataset.close,side:exitSide,event:'exit',order_type:'market',source:'strategy_production_console'})});setNotice("手动平仓已提交。");await load()}catch(error){setNotice(`平仓未完成：${error.message}`)}});
$("#tabs").addEventListener("click",event=>{const button=event.target.closest("[data-tab]");if(!button)return;$("#tabs .on").classList.remove("on");$(".tab.on").classList.remove("on");button.classList.add("on");$(`[data-panel="${button.dataset.tab}"]`).classList.add("on");if(button.dataset.tab==="supervisor")loadSupervisorAudit().catch(()=>{})});
$("#yesterdayPnlEvidence").addEventListener("click",event=>{if(!event.target.closest("[data-yesterday-review]"))return;const row=state.data?.yesterday_pnl||{},cycles=(row.supporting_packages||[]).map(item=>item.cycle_id).filter(Boolean),review=$("#review");if(review){review.querySelector("#yesterdayReviewContext")?.remove();review.insertAdjacentHTML("afterbegin",`<p class="hint" id="yesterdayReviewContext">Yesterday ${esc(row.report_date||"日期未知")} 支持的 12h packages：${esc(cycles.join("、")||"证据缺失")}。</p>`)}$("#tabs [data-tab=review]")?.click()});
window.addEventListener("pointerdown",armTradeAudio,{capture:true,passive:true});window.addEventListener("keydown",armTradeAudio,{capture:true});
gmRead.startReadModelPolling(load,{publicObserver:PUBLIC_OBSERVER,isBusy:()=>state.busy});
